import Vue from 'vue'
import VueRouter from 'vue-router'
import RecruitmentPage from '../views/RecruitmentPage.vue'
import RecruitmentInfoPage from '../views/RecruitmentInfoPage.vue'
import HomePage from '../views/HomePage.vue'
import SchoolOverview from '../views/SchoolOverview.vue'
import MoralEducation from '@/views/MoralEducation'

Vue.use(VueRouter)

const routes = [
  {
    path: '/',
    redirect: '/home'  // 将根路径重定向到/home
  },
  {
    path: '/home',
    name: 'Home',
    component: HomePage
  },
  {
    path: '/about',
    name: 'About',
    component: SchoolOverview
  },
  // 添加教学教研页面路由
  {
    path: '/teaching',
    name: 'Teaching',
    component: TeachingPage
  },
  {
    path: '/admission',
    name: 'Admission',
    component: RecruitmentPage,
    props: { activeTab: 'admission' }
  },
  {
    path: '/recruitment',
    name: 'Recruitment',
    component: RecruitmentPage,
    props: { activeTab: 'recruitment' }
  },
  {
    path: '/recruitment-info',
    name: 'RecruitmentInfo',
    component: RecruitmentInfoPage
  },
  {
    path: '/registration',
    name: 'Registration',
    component: RecruitmentPage,
    props: { activeTab: 'registration' }
  },
  {
    path: '/contact',
    name: 'Contact',
    component: RecruitmentPage,
    props: { activeTab: 'contact' }
  },
  // 添加校园文化路由
  {
    path: '/culture',
    name: 'Culture',
    component: CampusCulture
  },
  {
    path: '/moral-education',
    name: 'MoralEducation',
    component: MoralEducation
  }
]

const router = new VueRouter({
  mode: 'history',
  base: process.env.BASE_URL,
  routes
})

export default router
